steps.codeExample:
CREATE TABLE alunos (
    id SERIAL PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    idade INT CHECK (idade >= 16)
);

CREATE TABLE matriculas (
    id SERIAL PRIMARY KEY,
    aluno_id INT NOT NULL REFERENCES alunos(id) ON DELETE CASCADE,
    nota NUMERIC CHECK (nota >= 0 AND nota <= 10)
);

